tasks.answer:
def diagnose(s):
    pairs = {')': '(', '}': '{', ']': '['}
    stack = []
    for ch in s:
        if ch in '({[':
            stack.append(ch)
        elif ch in pairs:
            if not stack:
                return '오른쪽 괄호가 더 많음'
            if stack.pop() != pairs[ch]:
                return '괄호의 종류가 어긋남'
    if stack:
        return '왼쪽 괄호가 남음'
    return '오류 없음'

for t in ['A[(i+1)] = 0', 'if ((i==0) && (j==0)', 'while (i < 10) ) :', 'A[(i+1] ) = 0']:
    print(t, '→', diagnose(t))
